#!/usr/bin/env bash
# Usage: install-cargo-about.sh <dest-dir>
#
# Installs a pinned cargo-about release into <dest-dir> after verifying its
# SHA-256, so the CI license check and the release notices are generated by
# the same, publicly visible tool version. Under GitHub Actions it also
# exports CARGO_ABOUT for scripts/generate-third-party-licenses.sh. Only the
# Linux x86_64 runners that generate the notices are pinned.
set -euo pipefail

# shellcheck source=scripts/lib/verified-download.sh
source "$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)/lib/verified-download.sh"

CARGO_ABOUT_VERSION=0.9.3

dest=${1-}
base_url=${CARGO_ABOUT_BASE_URL:-https://github.com/EmbarkStudios/cargo-about/releases/download/${CARGO_ABOUT_VERSION}}
platform=${CARGO_ABOUT_PLATFORM:-$(uname -s)-$(uname -m)}

die() {
  printf 'ERROR: %s\n' "$*" >&2
  exit 1
}

[[ -n "${dest}" ]] || die "usage: $0 <dest-dir>"

case "${platform}" in
  Linux-x86_64)
    name=cargo-about-${CARGO_ABOUT_VERSION}-x86_64-unknown-linux-musl
    sha256=3ad1e94ea1e63d69d1961f4fb15ccbbe9575d906111f96d2cb4dce6df48f71b4
    ;;
  *)
    die "no pinned cargo-about for platform ${platform}"
    ;;
esac

work=$(mktemp -d)
trap 'rm -rf "${work}"' EXIT

verified_download "${base_url}/${name}.tar.gz" "${sha256}" "${work}/${name}.tar.gz"
tar -xzf "${work}/${name}.tar.gz" -C "${work}"
mkdir -p "${dest}"
cp "${work}/${name}/cargo-about" "${dest}/cargo-about"
"${dest}/cargo-about" --version

if [[ -n "${GITHUB_ENV-}" ]]; then
  echo "CARGO_ABOUT=${dest}/cargo-about" >>"${GITHUB_ENV}"
fi
